commands.command:
mysql -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.orders (
  id INT PRIMARY KEY AUTO_INCREMENT,
  customer VARCHAR(64),
  amount DECIMAL(10,2),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO appdb.orders (customer, amount) VALUES ('alice', 100.50), ('bob', 250.00), ('carol', 75.25);
SELECT COUNT(*) AS row_count FROM appdb.orders;
"
